-- Versioned, database-configurable combat reward inputs. Monster rows must be
-- populated from Wakfu evidence; Dofus IDs/data are never copied implicitly.
CREATE TABLE combat_reward_policy_versions (
    version integer PRIMARY KEY CHECK (version > 0),
    xp_rate_bp integer NOT NULL CHECK (xp_rate_bp BETWEEN 0 AND 1000000),
    kamas_rate_bp integer NOT NULL CHECK (kamas_rate_bp BETWEEN 0 AND 1000000),
    conquest_rate_bp integer NOT NULL CHECK (conquest_rate_bp BETWEEN 0 AND 1000000),
    created_at timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP
);
VALUES (1,10000,10000,10000);

CREATE TABLE combat_reward_policy_active (
    singleton boolean PRIMARY KEY DEFAULT true CHECK (singleton),
    version integer NOT NULL REFERENCES combat_reward_policy_versions(version)
);

CREATE TABLE combat_reward_monster_levels (
    monster_reference integer NOT NULL CHECK (monster_reference > 0),
    monster_level smallint NOT NULL CHECK (monster_level BETWEEN 1 AND 200),
    base_xp bigint NOT NULL CHECK (base_xp BETWEEN 0 AND 9223372036854775807),
    min_kamas integer NOT NULL CHECK (min_kamas BETWEEN 0 AND 2147483647),
    max_kamas integer NOT NULL CHECK (max_kamas BETWEEN min_kamas AND 2147483647),
    source text NOT NULL CHECK (length(source) BETWEEN 1 AND 160),
    PRIMARY KEY (monster_reference,monster_level)
);

-- A level-based emulation fallback is kept separate from Wakfu-specific
-- reference overrides. Its provenance must identify the imported policy.
CREATE TABLE combat_reward_level_defaults (
    monster_level smallint PRIMARY KEY CHECK (monster_level BETWEEN 1 AND 200),
    base_xp bigint NOT NULL CHECK (base_xp BETWEEN 0 AND 9223372036854775807),
    min_kamas integer NOT NULL CHECK (min_kamas BETWEEN 0 AND 2147483647),
    max_kamas integer NOT NULL CHECK (max_kamas BETWEEN min_kamas AND 2147483647),
    source text NOT NULL CHECK (length(source) BETWEEN 1 AND 160)
);

CREATE TABLE fight_reward_policy_receipts (
    fight_id integer NOT NULL,
    character_id bigint NOT NULL,
    account_id bigint NOT NULL,
    generation text NOT NULL CHECK (length(generation)>0),
    policy_version integer NOT NULL REFERENCES combat_reward_policy_versions(version),
    snapshot jsonb NOT NULL CHECK (jsonb_typeof(snapshot)='object'),
    snapshot_sha256 char(64) NOT NULL CHECK (snapshot_sha256 ~ '^[0-9a-f]{64}$'),
    xp bigint NOT NULL CHECK (xp BETWEEN 0 AND 9223372036854775807),
    kamas integer NOT NULL CHECK (kamas BETWEEN 0 AND 2147483647),
    created_at timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY (fight_id,character_id),
    FOREIGN KEY (fight_id,character_id,account_id)
        REFERENCES combat_fight_participants(fight_id,character_id,account_id)
);

-- Local Dofus-derived level fallback, not Wakfu-native balance or cross-ID data.
-- Source policy and reproducible extraction are documented by dofus-reward-level-reference.json.
